// ─── companyLogo.js ─────────────────────────────────────────────────────────
// The Mahendra Industries logo, embedded as a base64 data URI. Kept in its
// own file (not inline in POPrintView.jsx) so swapping the logo later is a
// one-file change. The print window is fully standalone HTML opened via
// window.open() — it can not reference /public asset paths from the app, so
// the logo has to be embedded rather than linked.
//
// To update the logo: replace the data URI below with a new one. Any image
// tool can produce it, e.g. in a terminal:
//   base64 -i new-logo.png | pbcopy   (then wrap as data:image/png;base64,...)

export const COMPANY_LOGO_DATA_URI = "data:image/jpeg;base64,";
